CREATE TABLE IF NOT EXISTS mrp_runs(mrp_run_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,plan_id TEXT,run_no TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',planning_date TEXT,notes TEXT,created_by TEXT NOT NULL,approved_by TEXT,approved_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,run_no));
CREATE TABLE IF NOT EXISTS mrp_requirements(mrp_requirement_id TEXT PRIMARY KEY,mrp_run_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,product_master_id TEXT NOT NULL,material_master_id TEXT NOT NULL,requirement_type TEXT NOT NULL,gross_requirement NUMERIC NOT NULL,scheduled_receipt NUMERIC NOT NULL DEFAULT 0,on_hand NUMERIC NOT NULL DEFAULT 0,safety_stock NUMERIC NOT NULL DEFAULT 0,projected_available NUMERIC NOT NULL DEFAULT 0,shortage_qty NUMERIC NOT NULL DEFAULT 0,suggested_order_qty NUMERIC NOT NULL DEFAULT 0,uom TEXT NOT NULL,source_plan_line_id TEXT,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(mrp_run_id) REFERENCES mrp_runs(mrp_run_id));
CREATE INDEX IF NOT EXISTS ix_mrp_req_scope ON mrp_requirements(organization_id,entity_id,location_id,material_master_id,mrp_run_id);
CREATE TABLE IF NOT EXISTS mrp_plan_exceptions(exception_id TEXT PRIMARY KEY,mrp_run_id TEXT NOT NULL,material_master_id TEXT NOT NULL,exception_type TEXT NOT NULL,severity TEXT NOT NULL,shortage_qty NUMERIC NOT NULL DEFAULT 0,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',resolved_by TEXT,resolved_at TIMESTAMP,resolution_note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
